/**
 * 根据当前主题获取对应的图标
 *
 * @param key 图标键名（与 icons 对象中的 key 相同）
 * @returns 对应主题的 SVG 字符串，深色主题不存在时回退到浅色
 */
export function getIcon(key: keyof typeof icons): string {
  const isDark = document.documentElement.classList.contains('dark');
  if (isDark && key in darkIcons) {
    return darkIcons[key];
  }
  return icons[key];
}

// ---------------------------------------------------------------------------
// 主题变化订阅
// ---------------------------------------------------------------------------

/** 主题深浅切换的回调，参数为切换后的是否深色 */
type IconThemeListener = (isDark: boolean) => void;

/** 已注册的主题变化回调 */
const themeListeners = new Set<IconThemeListener>();

/** 监听 documentElement class 变化的观察者（懒启动，无监听者时自动断开） */
let themeObserver: MutationObserver | null = null;

/** 当前深色状态缓存，用于过滤无关的 class 变化 */
let currentIsDark =
  typeof document !== 'undefined' && document.documentElement.classList.contains('dark');

/** 确保主题观察者已启动 */
function ensureThemeObserver(): void {
  if (themeObserver || typeof document === 'undefined') return;

  themeObserver = new MutationObserver(() => {
    const isDark = document.documentElement.classList.contains('dark');
    // 仅在深浅状态真正翻转时才通知，避免主题类频繁增删导致的无效回调
    if (isDark !== currentIsDark) {
      currentIsDark = isDark;
      themeListeners.forEach((cb) => cb(isDark));
    }
  });

  themeObserver.observe(document.documentElement, {
    attributes: true,
    attributeFilter: ['class'],
  });
}

/**
 * 订阅深浅主题变化。
 *
 * 与 getIcon 配合使用：当主题在运行时切换（如菜单正打开着时），
 * 订阅方可在回调里用 getIcon 重新取图标并更新 DOM，实现实时切换。
 *
 * @param listener 主题翻转时触发的回调
 * @returns 取消订阅的函数；当最后一个监听者取消后，观察者自动断开
 */
export function onIconThemeChange(listener: IconThemeListener): () => void {
  themeListeners.add(listener);
  ensureThemeObserver();

  return () => {
    themeListeners.delete(listener);
    if (themeListeners.size === 0 && themeObserver) {
      themeObserver.disconnect();
      themeObserver = null;
    }
  };
}
